    /**
     * @param  array<string, string>  $values
     * @return array{group: string, key: string, values: array<string, string>, description: null, is_system: bool}
     */
    protected function entry(string $group, string $key, array $values): array
    {
        return [
            'group' => $group,
            'key' => $key,
            'description' => null,
            'is_system' => true,
            'values' => $values,
        ];
    }

